-- 22-검증. 094000 적용 직후 (조회 전용). 모든 ok 가 true 여야 합니다.
SELECT no, item, actual, expected,
       CASE WHEN expected = '기록용' THEN NULL ELSE actual IS NOT DISTINCT FROM expected END AS ok
FROM (VALUES
    (1, '항목 잠금 트리거(항목 12종, 활성)', (SELECT count(*)::text FROM pg_trigger WHERE tgname = 'trg_daily_log_item_parent_unlocked' AND tgrelid = ANY (ARRAY(SELECT to_regclass('public.' || t)::oid FROM unnest(ARRAY['daily_hygiene_log_items', 'daily_temp_humidity_log_items', 'daily_sanitation_facility_log_items', 'daily_worker_hygiene_log_items', 'daily_cold_storage_hygiene_log_items', 'daily_process_control_bread_log_items', 'daily_material_storage_3f_log_items', 'daily_manufacturing_equipment_log_items', 'daily_air_conditioning_equipment_log_items', 'daily_hoist_inspection_log_items', 'daily_illumination_log_items', 'daily_material_receiving_inspection_log_items']::text[]) t)) AND tgenabled <> 'D'), '12'),
    (2, '항목 잠금 함수', (to_regprocedure('public.enforce_daily_log_item_parent_unlocked()') IS NOT NULL)::text, 'true'),
    (3, '정정 요청 함수', (to_regprocedure('public.request_daily_log_correction(text, uuid, text)') IS NOT NULL)::text, 'true'),
    (4, '정정 요청 함수 소유자 권한 실행(SECURITY DEFINER)', (SELECT prosecdef::text FROM pg_proc WHERE oid = to_regprocedure('public.request_daily_log_correction(text, uuid, text)')), 'true'),
    (5, '정정 요청 함수 실행 권한 anon', has_function_privilege('anon', 'public.request_daily_log_correction(text, uuid, text)', 'EXECUTE')::text, 'false'),
    (6, '정정 요청 함수 실행 권한 authenticated', has_function_privilege('authenticated', 'public.request_daily_log_correction(text, uuid, text)', 'EXECUTE')::text, 'true'),
    (7, 'data_corrections.kind / requested_by 컬럼', ((EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'data_corrections' AND column_name = 'kind'))::text || '/' || (EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'data_corrections' AND column_name = 'requested_by'))::text), 'true/true'),
    (8, 'data_corrections 종류 제약', (EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'data_corrections_kind_check' AND conrelid = 'public.data_corrections'::regclass))::text, 'true'),
    (9, 'data_corrections 추가 전용 트리거 유지', (SELECT count(*)::text FROM pg_trigger WHERE tgrelid = 'public.data_corrections'::regclass AND tgname IN ('trg_data_corrections_append_only','trg_data_corrections_no_truncate')), '2'),
    (10, 'data_corrections 기존 행 중 reopen 아닌 것(기록용, 사전 점검 행 수와 같아야 함)', (SELECT count(*)::text FROM public.data_corrections WHERE kind = 'direct_sql'), '기록용'),
    (11, '091000 유지', (SELECT count(*)::text FROM pg_trigger WHERE tgname = 'trg_daily_log_approval_times' AND tgrelid = ANY (ARRAY(SELECT to_regclass('public.' || t)::oid FROM unnest(ARRAY['daily_hygiene_logs', 'daily_temp_humidity_logs', 'daily_sanitation_facility_logs', 'daily_worker_hygiene_logs', 'daily_cold_storage_hygiene_logs', 'daily_process_control_bread_logs', 'daily_material_storage_3f_logs', 'daily_manufacturing_equipment_logs', 'daily_air_conditioning_equipment_logs', 'daily_hoist_inspection_logs', 'daily_illumination_logs', 'daily_material_receiving_inspection_logs', 'daily_raw_thawing_logs']::text[]) t)) AND tgenabled <> 'D'), '13'),
    (12, '096000 아직 없음', (SELECT count(*)::text FROM pg_trigger WHERE tgname = 'trg_daily_log_edit_rights' AND tgrelid = ANY (ARRAY(SELECT to_regclass('public.' || t)::oid FROM unnest(ARRAY['daily_hygiene_logs', 'daily_temp_humidity_logs', 'daily_sanitation_facility_logs', 'daily_worker_hygiene_logs', 'daily_cold_storage_hygiene_logs', 'daily_process_control_bread_logs', 'daily_material_storage_3f_logs', 'daily_manufacturing_equipment_logs', 'daily_air_conditioning_equipment_logs', 'daily_hoist_inspection_logs', 'daily_illumination_logs', 'daily_material_receiving_inspection_logs', 'daily_raw_thawing_logs']::text[]) t)) AND tgenabled <> 'D'), '0')
) AS v(no, item, actual, expected)
ORDER BY no;
